-- 3. Especies (363). `identification_tips` va como texto separado por «; », que es como lo parte park_payload.php.
-- ------------------------------------------------------------------------------------------------
INSERT INTO species (park_id, common_name, scientific_name, kingdom, family, primary_habitat, conservation_status, description, description_source, identification_tips, seasonality, image_url, image_attribution, latitude, longitude, rarity_score, rarity_basis, rarity_local, rarity_local_basis, is_featured, is_visible, hidden_reason, source, taxon_phylum, taxon_class, taxon_order, taxon_family, taxon_genus, iucn_global, spain_status, murcia_status, review_note, eidos_taxonid, gbif_species_key, zepa_site_code)
SELECT pk.id, s.common_name, s.scientific_name, s.kingdom, s.family, s.primary_habitat, s.conservation_status, s.description, s.description_source, s.identification_tips, s.seasonality, s.image_url, s.image_attribution, s.latitude, s.longitude, s.rarity_score, s.rarity_basis, s.rarity_local, s.rarity_local_basis, s.is_featured, s.is_visible, s.hidden_reason, s.source, s.taxon_phylum, s.taxon_class, s.taxon_order, s.taxon_family, s.taxon_genus, s.iucn_global, s.spain_status, s.murcia_status, s.review_note, s.eidos_taxonid, s.gbif_species_key, s.zepa_site_code
FROM parks pk JOIN (
    SELECT 'Jabalí' common_name, 'Sus scrofa' scientific_name, 'fauna' kingdom, 'Mamífero ungulado' family, 'Bosque, matorral denso y cultivos; necesita cobertura y puntos de agua' primary_habitat, 'LC' conservation_status, 'Ungulado robusto y adaptable, con el cuerpo cubierto de cerdas ásperas y una cabeza en cuña rematada por un hocico potente con el que remueve el suelo. Los rayones —las crías— nacen con líneas claras a lo largo del lomo. Es omnívoro y ha ampliado mucho su área en las últimas décadas.' description, NULL description_source, 'Hozaduras: zonas de suelo removido como si lo hubieran arado; Huellas hendidas grandes con las pezuñas laterales marcadas; Barros y árboles con el tronco embarrado a media altura' identification_tips, 'Todo el año (actividad sobre todo nocturna)' seasonality, 'https://commons.wikimedia.org/wiki/Special:FilePath/Eberswalde_Zoo_12-2017_img2.jpg?width=1280' image_url, 'A.Savin (FAL) · Wikimedia Commons' image_attribution, NULL latitude, NULL longitude, 1 rarity_score, '{"categoria":"Sin figura de protección","ambito":"estatal","origen":"spainStatus del catálogo universal"}' rarity_basis, 1 rarity_local, NULL rarity_local_basis, 0 is_featured, 1 is_visible, NULL hidden_reason, 'GBIF: 255 ocurrencias dentro de los polígonos de hábitat del espacio (4 hábitats; barrido de 2026-08-16); EIDOS (IEPNB, MITECO) para la taxonomía; sin figura de protección en la vista de normas' source, 'Chordata' taxon_phylum, 'Mammalia' taxon_class, 'Artiodactyla' taxon_order, 'Suidae' taxon_family, 'Sus' taxon_genus, 'LC' iucn_global, 'No catalogada (especie cinegética común)' spain_status, 'No incluida en el Catálogo Regional de especies protegidas (Región de Murcia)' murcia_status, NULL review_note, 12178 eidos_taxonid, 7705930 gbif_species_key, NULL zepa_site_code
    UNION ALL
    SELECT 'Zorro', 'Vulpes vulpes', 'fauna', 'Mamífero carnívoro', 'Prácticamente cualquier ambiente: bosque, matorral, cultivos y periferias urbanas', 'LC', 'El carnívoro silvestre más adaptable y extendido: vive desde la alta montaña hasta el borde de las ciudades. Es omnívoro y oportunista, lo que explica su éxito. Se reconoce por la cola larga y espesa —la «hopa»— rematada casi siempre en blanco.', NULL, 'Cola muy espesa con la punta blanca; Huella alargada con las cuatro almohadillas alineadas; Excrementos retorcidos y con pelos, sobre piedras y caminos', 'Todo el año (actividad sobre todo nocturna)', 'https://commons.wikimedia.org/wiki/Special:FilePath/Vulpes_vulpes_2.jpg?width=1280', 'Juan Lacruz (CC BY-SA 3.0) · Wikimedia Commons', NULL, NULL, 1, '{"categoria":"Sin figura de protección","ambito":"estatal","origen":"spainStatus del catálogo universal"}', 1, NULL, 0, 1, NULL, 'GBIF: 189 ocurrencias dentro de los polígonos de hábitat del espacio (4 hábitats; barrido de 2026-08-16); EIDOS (IEPNB, MITECO) para la taxonomía; sin figura de protección en la vista de normas', 'Chordata', 'Mammalia', 'Carnivora', 'Canidae', 'Vulpes', 'LC', 'No catalogada (especie cinegética común)', 'No incluida en el Catálogo Regional de especies protegidas (Región de Murcia)', NULL, 12419, 5219243, NULL
    UNION ALL
    SELECT 'Albaida', 'Anthyllis cytisoides', 'flora', 'Mata', 'Matorral seco y soleado sobre margas y suelos pobres', 'No catalogada', 'Mata de aspecto blanquecino por la fina pelusa que cubre hojas y tallos, un recurso frente al sol y la sequía. En primavera se llena de espigas de flores amarillas que atraen a muchos insectos. Es una de las leguminosas que primero coloniza laderas degradadas y taludes.', NULL, 'Aspecto grisáceo y aterciopelado al tacto; Flores amarillas pequeñas en espigas apretadas; Hojas divididas en tres, la del centro más larga', 'Primavera', 'https://commons.wikimedia.org/wiki/Special:FilePath/Anthyllis_cytisoides.JPG?width=1280', 'Ximenex (CC BY-SA 2.1 es) · Wikimedia Commons', NULL, NULL, 1, '{"categoria":"Sin figura de protección","ambito":"estatal","origen":"spainStatus del catálogo universal"}', 1, NULL, 0, 1, NULL, 'GBIF: 117 ocurrencias dentro de los polígonos de hábitat del espacio (8 hábitats; barrido de 2026-08-16); EIDOS (IEPNB, MITECO) para la taxonomía; sin figura de protección en la vista de normas', 'Tracheophyta', 'Magnoliopsida', 'Fabales', 'Fabaceae', 'Anthyllis', 'No evaluada específicamente en la Lista Roja mundial de la UICN (especie muy común)', 'No incluida en la Lista Roja de la Flora Vascular Española (2008) ni en el LESRPE', 'No incluida en el Catálogo Regional de especies protegidas (Región de Murcia)', NULL, 2186, 5352466, NULL
    UNION ALL
    SELECT 'Pino carrasco', 'Pinus halepensis', 'flora', 'Conífera', 'Laderas secas y soleadas sobre calizas y margas, en clima mediterráneo cálido', 'LC', 'Pino de copa clara e irregular y follaje de un verde pálido, el más resistente a la sequía y a los suelos pobres de los pinos ibéricos. Sus piñas, alargadas y asimétricas, quedan colgadas años en la rama y liberan las semillas tras los incendios, lo que le permite recolonizar rápido.', NULL, 'Copa irregular y poco densa, de verde claro; Piñas asimétricas y persistentes, apuntando hacia atrás; Corteza clara y agrietada, rojiza en las ramas jóvenes', 'Todo el año', 'https://commons.wikimedia.org/wiki/Special:FilePath/Pino_secolare_-_Castelleone_di_Suasa.JPG?width=1280', 'Accurimbono (CC BY-SA 3.0) · Wikimedia Commons', NULL, NULL, 1, '{"categoria":"Sin figura de protección","ambito":"estatal","origen":"spainStatus del catálogo universal"}', 1, NULL, 0, 1, NULL, 'GBIF: 102 ocurrencias dentro de los polígonos de hábitat del espacio (6 hábitats; barrido de 2026-08-16); EIDOS (IEPNB, MITECO) para la taxonomía; sin figura de protección en la vista de normas', 'Tracheophyta', 'Pinopsida', 'Pinales', 'Pinaceae', 'Pinus', 'LC', 'No catalogada (especie forestal común)', 'No incluida en el Catálogo Regional de especies protegidas (Región de Murcia)', NULL, 7118, 5285604, NULL
    UNION ALL
    SELECT 'Espino negro', 'Rhamnus lycioides', 'flora', 'Arbusto', NULL, 'No catalogada', 'Es un arbustillo de hasta 3 m de altura (López González, 2001), que frecuentemente tiene aspecto de mata alta o media, más o menos espinoso, de ramificación intricada y de perennifolio a semicaducifolio facultativo. Sus especímenes tienen espinas pero presentan una variabilidad: los de las regiones continentales y mediterráneas más áridas las llegan a tener en cantidad y longitud exagerada, pero otros son casi inermes. Presenta también unas ramillas laterales cortas terminadas en un fascículo de hojas. Éstas se disponen alternas, aunque a veces algunas se muestran casi opuestas; son simples, sin peciolo y con un limbo estrecho (tíìcamente menor de 0,5 cm), a veces muy corto, menor de 1,2 cm (subsp. borgiae), de trasovado-oblongo a espatulado-linear, lampiño o con un pelillo muy corto (subesp. velutina).', NULL, NULL, 'Todo el año', 'https://commons.wikimedia.org/wiki/Special:FilePath/Rhamnus_lycioides_fruits.JPG?width=1280', 'איתן פרמן (CC BY-SA 3.0) · Wikimedia Commons', NULL, NULL, 1, '{"categoria":"Sin figura de protección","ambito":"estatal","origen":"spainStatus del catálogo universal"}', 1, NULL, 0, 1, NULL, 'GBIF: 84 ocurrencias dentro de los polígonos de hábitat del espacio (6 hábitats; barrido de 2026-08-16); EIDOS (IEPNB, MITECO) para la taxonomía; sin figura de protección en la vista de normas', 'Tracheophyta', 'Magnoliopsida', 'Rosales', 'Rhamnaceae', 'Rhamnus', 'No evaluada en la Lista Roja mundial de la UICN', 'Sin figura de protección de ámbito estatal (LESRPE/CEEA) en EIDOS (IEPNB)', 'No incluida en el Catálogo Regional de especies protegidas (Región de Murcia)', NULL, 7730, 6371380, NULL
    UNION ALL
    SELECT 'Jara blanca', 'Cistus albidus', 'flora', 'Mata', 'Matorral y laderas soleadas sobre suelos calizos secos', 'No catalogada', 'Jara de hojas blanquecinas, aterciopeladas al tacto y sin peciolo, con flores grandes de color rosa malva y pétalos arrugados como papel de seda que duran solo unas horas. Es una de las plantas que da color al matorral en primavera.', NULL, 'Hojas blanquecinas y aterciopeladas, sentadas en la rama; Flores rosa malva grandes, de pétalos arrugados; Cada flor dura apenas una mañana', 'Primavera', 'https://commons.wikimedia.org/wiki/Special:FilePath/Cistus_albidus_flowers.jpg?width=1280', 'Júlio Reis (CC BY-SA 3.0) · Wikimedia Commons', NULL, NULL, 1, '{"categoria":"Sin figura de protección","ambito":"estatal","origen":"spainStatus del catálogo universal"}', 1, NULL, 0, 1, NULL, 'GBIF: 65 ocurrencias dentro de los polígonos de hábitat del espacio (7 hábitats; barrido de 2026-08-16); EIDOS (IEPNB, MITECO) para la taxonomía; sin figura de protección en la vista de normas', 'Tracheophyta', 'Magnoliopsida', 'Malvales', 'Cistaceae', 'Cistus', 'No evaluada específicamente en la Lista Roja mundial de la UICN', 'Sin figura de protección nacional específica registrada en EIDOS', 'No incluida en el Catálogo Regional de especies protegidas (Región de Murcia)', NULL, 3609, 7331435, NULL
    UNION ALL
    SELECT 'Lentisco', 'Pistacia lentiscus', 'flora', 'Arbusto', 'Matorral mediterráneo litoral', 'LC', 'Arbusto perennifolio de hojas compuestas sin foliolo terminal y con el raquis alado, un detalle que lo separa de la cornicabra. Al frotarlo huele intensamente a resina. Sus frutos, en racimo, pasan de rojo a negro y son alimento clave para aves en otoño.', NULL, 'Hoja compuesta con número par de foliolos, sin uno terminal; Raquis de la hoja con dos alas laterales; Olor fuerte a resina al frotar las hojas', 'Todo el año', 'https://commons.wikimedia.org/wiki/Special:FilePath/Pistacia_lentiscus.jpg?width=1280', 'Lumbar~commonswiki (CC BY-SA 3.0) · Wikimedia Commons', NULL, NULL, 1, '{"categoria":"Sin figura de protección","ambito":"estatal","origen":"spainStatus del catálogo universal"}', 1, NULL, 0, 1, NULL, 'GBIF: 59 ocurrencias dentro de los polígonos de hábitat del espacio (7 hábitats; barrido de 2026-08-16); EIDOS (IEPNB, MITECO) para la taxonomía; sin figura de protección en la vista de normas', 'Tracheophyta', 'Magnoliopsida', 'Sapindales', 'Anacardiaceae', 'Pistacia', 'LC', 'No catalogada (especie común mediterránea)', 'No incluida en el Catálogo Regional de especies protegidas (Región de Murcia)', NULL, 7129, 3190583, NULL
    UNION ALL
    SELECT 'Romero', 'Rosmarinus officinalis', 'flora', 'Mata aromática', 'Matorral seco y soleado sobre suelos calizos y pedregosos', 'No catalogada', 'Arbusto aromático de hojas estrechas como agujas, verde oscuro por el haz y blanquecinas por el envés, con los bordes enrollados hacia abajo. Florece casi todo el año en azul pálido, y en pleno invierno es una de las pocas fuentes de néctar del matorral.', NULL, 'Hojas como agujas, blancas por debajo; Olor inconfundible al frotar entre los dedos; Flores azul claro repartidas por las ramas casi todo el año', 'Todo el año, con máximo de floración en invierno y primavera', 'https://commons.wikimedia.org/wiki/Special:FilePath/Rosemary_in_bloom.JPG?width=1280', 'Margalob (CC BY-SA 4.0) · Wikimedia Commons', NULL, NULL, 1, '{"categoria":"Sin figura de protección","ambito":"estatal","origen":"spainStatus del catálogo universal"}', 1, NULL, 0, 1, NULL, 'GBIF: 55 ocurrencias dentro de los polígonos de hábitat del espacio (6 hábitats; barrido de 2026-08-16); EIDOS (IEPNB, MITECO) para la taxonomía; sin figura de protección en la vista de normas', 'Tracheophyta', 'Magnoliopsida', 'Lamiales', 'Lamiaceae', 'Rosmarinus', 'No evaluada específicamente en la Lista Roja mundial de la UICN (especie muy común)', 'No incluida en la Lista Roja de la Flora Vascular Española (2008) ni en el LESRPE', 'No incluida en el Catálogo Regional de especies protegidas (Región de Murcia)', 'Seleccionada como *Salvia rosmarinus*; se ficha con el nombre aceptado en EIDOS, que es con el que el resto del catálogo la tiene desde la revisión nomenclatural posterior a la selección.', 7647, 10902460, NULL
    UNION ALL
    SELECT 'Candil', 'Arisarum vulgare', 'flora', 'Hierba', 'Se encuentra en cultivos, bordes de camino y en grietas, en lugares nitrificados sobre sustratos básicos, hasta 1200 m', 'No catalogada', 'Planta perenne, herbácea, con rizoma del que crecen sus raíces. Hojas con largo pecíolo, hasta de 40 cm, y limbo cordiforme o hastado. Inflorescencia que nace sobre un pedúnculo erecto, con manchas color violeta. Espata alargada, hasta de 7 cm, cilíndrica, recurvada arriba, con ápice agudo, color morado oscuro con franjas blancas longitudinales por abajo. Espádice 2-6 cm con las flores femeninas abajo y las masculinas por encima de estas, que llegan hasta un tercio del espádice. Frutillos en baya de 2-8 mm.', 'EIDOS (IEPNB, MITECO), v_atributos_pliniancore, atributo «Descripción de la especie»', NULL, 'Octubre a mayo', 'https://commons.wikimedia.org/wiki/Special:FilePath/Arisarum_vulgare_Mallorca_02.jpg?width=1280', 'Orchi (CC BY-SA 3.0) · Wikimedia Commons', NULL, NULL, 2, NULL, 2, '{"origen":"rarityScore estatal del catálogo universal: EIDOS no devolvió ninguna norma para este taxón al hacer la selección, y el tramo local no puede quedar por debajo del estatal"}', 0, 1, NULL, 'GBIF: 50 ocurrencias dentro de los polígonos de hábitat del espacio (5 hábitats; barrido de 2026-08-16); EIDOS (IEPNB, MITECO) para la taxonomía; sin figura de protección en la vista de normas', 'Tracheophyta', 'Liliopsida', 'Alismatales', 'Araceae', 'Arisarum', 'No evaluada en la Lista Roja mundial de la UICN', 'Sin figura de protección de ámbito estatal (LESRPE/CEEA) en EIDOS (IEPNB)', 'No incluida en el Catálogo Regional de especies protegidas (Región de Murcia)', NULL, 2418, 2867495, NULL
    UNION ALL
    SELECT 'Asperillo', 'Lithodora fruticosa', 'flora', 'Mata', 'Vive en claros de encinar, matorrales soleados y pedregales, sobre sustratos básicos, entre 40-2100 m', 'No catalogada', 'Mata leñosa hasta de 90 cm, híspida, con tallos muy ramificados, blanquecinos o grisáceos. Hojas de 8-20 x 1-2,5 mm, alternas, lineares, cubiertas de pelos ásperos blanquecinos. Una o dos flores en la parte terminal de las ramillas, rodeadas de brácteas largas. Cáliz tubular, de 5-7 mm, dividido hasta cerca de la base. Corola de 10-18 x 8-12 mm, regular o actinomorfa, infundibuliforme, azul, violácea o rojiza, con cinco lóbulos anchos y poco profundos, abiertos en estrella, algo pelosos por fuera y glabros en el interior. Cinco estambres no exertos, con anteras de 2-3 mm, amarillentas. Estilo incluído o algo exerto. Fruto formado por una o dos núculas de 3,5-4,5 x 2-2,5 mm, grisáceas.', NULL, NULL, 'Octubre, enero, febrero, marzo, abril, mayo, junio', 'https://commons.wikimedia.org/wiki/Special:FilePath/Lithodora_fruticosa2.jpg?width=1280', 'Nanosanchez (Public domain) · Wikimedia Commons', NULL, NULL, 1, '{"categoria":"Sin figura de protección","ambito":"estatal","origen":"spainStatus del catálogo universal"}', 1, NULL, 0, 1, NULL, 'GBIF: 42 ocurrencias dentro de los polígonos de hábitat del espacio (6 hábitats; barrido de 2026-08-16); EIDOS (IEPNB, MITECO) para la taxonomía; sin figura de protección en la vista de normas', 'Tracheophyta', 'Magnoliopsida', 'Boraginales', 'Boraginaceae', 'Lithodora', 'No evaluada en la Lista Roja mundial de la UICN', 'Sin figura de protección de ámbito estatal (LESRPE/CEEA) en EIDOS (IEPNB)', 'No incluida en el Catálogo Regional de especies protegidas (Región de Murcia)', NULL, 5933, 5661164, NULL
    UNION ALL
    SELECT 'Algarrobo', 'Ceratonia siliqua', 'flora', 'Árbol', 'Laderas cálidas, antiguos cultivos y matorral del piso termomediterráneo', 'LC', 'Árbol perennifolio de copa densa y hojas compuestas con foliolos redondeados y lustrosos. Florece en otoño directamente sobre el tronco y las ramas viejas. Sus vainas pardas y dulces, las algarrobas, se han usado durante siglos como pienso y alimento.', NULL, 'Hojas compuestas de foliolos redondos y brillantes; Flores nacidas directamente del tronco y las ramas gruesas; Vainas pardas y aplanadas colgando del árbol', 'Todo el año', 'https://commons.wikimedia.org/wiki/Special:FilePath/Ceratonia_siliqua_Keciboynuzu_1370984_Nevit.jpg?width=1280', 'Nevit Dilmen (talk) (CC BY-SA 3.0) · Wikimedia Commons', NULL, NULL, 1, '{"categoria":"Sin figura de protección","ambito":"estatal","origen":"spainStatus del catálogo universal"}', 1, NULL, 0, 1, NULL, 'GBIF: 41 ocurrencias dentro de los polígonos de hábitat del espacio (5 hábitats; barrido de 2026-08-16); EIDOS (IEPNB, MITECO) para la taxonomía; sin figura de protección en la vista de normas', 'Tracheophyta', 'Magnoliopsida', 'Fabales', 'Fabaceae', 'Ceratonia', 'LC (Preocupación menor) (evaluación UICN 2017)', 'ANEXO I. 2) Lista de taxones forestales para conservación ex situ (Real Decreto 159/2022, de 1 de marzo, sobre conservación de los recursos genéticos foresta…)', 'No incluida en el Catálogo Regional de especies protegidas (Región de Murcia)', NULL, 3422, 5356354, NULL
    UNION ALL
    SELECT 'Uña de gato', 'Sedum sediforme', 'flora', 'Planta suculenta', 'Prados calcáreos del Alysso-Sedion albi', 'No catalogada', 'Crasulácea perenne de hojas suculentas puntiagudas y flores amarillo-verdosas, muy extendida por Murcia en repisas rocosas y prados calcáreos; especie característica del hábitat prioritario.', NULL, 'Hojas carnosas puntiagudas; Inflorescencia amarillo pálido; Coloniza repisas y suelos esqueléticos', 'Verano', 'https://commons.wikimedia.org/wiki/Special:FilePath/Sedum_sediforme_hojas.jpg?width=1280', 'autor no indicado (CC BY-SA 3.0) · Wikimedia Commons', NULL, NULL, 1, '{"categoria":"Sin figura de protección","ambito":"estatal","origen":"spainStatus del catálogo universal"}', 1, NULL, 0, 1, NULL, 'GBIF: 40 ocurrencias dentro de los polígonos de hábitat del espacio (7 hábitats; barrido de 2026-08-16); Atlas y Manual de los Hábitats de España (MITECO, 2005): especie característica de alguno de los HIC cartografiados aquí; EIDOS (IEPNB, MITECO) para la taxonomía; sin figura de protección en la vista de normas', 'Tracheophyta', 'Magnoliopsida', 'Saxifragales', 'Crassulaceae', 'Sedum', 'No evaluada específicamente en la Lista Roja mundial de la UICN (especie muy común)', 'No incluida en la Lista Roja de la Flora Vascular Española (2008) ni en el LESRPE', 'No incluida en el Catálogo Regional de especies protegidas (Región de Murcia)', NULL, NULL, 4201784, NULL
    UNION ALL
    SELECT 'Jara', 'Cistus monspeliensis', 'flora', 'Arbusto', 'Forma jarales en etapas de sustitución de encinares y quejigares en lugares húmedos sobre sustratos ácidos, hasta 1200 m', 'LC', 'Arbusto hasta de 1,5 m, ramoso, compacto. Hojas de 15-45 x 2-7 mm, linear lanceoladas o estrechamente elípticas, con pelos simples y estrellados. Inflorescencia en cima con flores que crecen hacia un lado, con dos a nueve flores. Pétalos de 9-14 mm, blancos; estambres muy numerosos, desiguales. Cápsula de 4 mm, globosa, brillante, que se abre por cinco valvas.', 'EIDOS (IEPNB, MITECO), v_atributos_pliniancore, atributo «Descripción de la especie»', NULL, 'Todo el año', 'https://commons.wikimedia.org/wiki/Special:FilePath/Cistus_monspeliensis_2.JPG?width=1280', 'User:Xemenendura (CC BY-SA 2.1 es) · Wikimedia Commons', NULL, NULL, 1, NULL, 1, NULL, 0, 1, NULL, 'GBIF: 38 ocurrencias dentro de los polígonos de hábitat del espacio (5 hábitats; barrido de 2026-08-16); EIDOS (IEPNB, MITECO) para la taxonomía; sin figura de protección en la vista de normas', 'Tracheophyta', 'Magnoliopsida', 'Malvales', 'Cistaceae', 'Cistus', 'LC — Preocupación menor (Lista Roja mundial de la UICN, 2020)', 'Sin figura de protección de ámbito estatal (LESRPE/CEEA) en EIDOS (IEPNB)', 'No incluida en el Catálogo Regional de especies protegidas (Región de Murcia)', NULL, 3624, 2874030, NULL
    UNION ALL
    SELECT 'Coscoja', 'Quercus coccifera', 'flora', 'Arbusto', 'Matorral esclerófilo y sabinar', 'LC', 'Arbusto esclerófilo de hoja perenne y espinosa, integrante del matorral mediterráneo denso y de las orlas del sabinar.', NULL, 'Hojas coriáceas con margen espinoso; Bellota con cúpula de escamas punzantes; Porte arbustivo denso', 'Todo el año', 'https://commons.wikimedia.org/wiki/Special:FilePath/Quercus_coccifera_1.JPG?width=1280', 'User:Xemenendura (CC BY-SA 3.0) · Wikimedia Commons', NULL, NULL, 2, NULL, 2, '{"origen":"rarityScore estatal del catálogo universal: EIDOS no devolvió ninguna norma para este taxón al hacer la selección, y el tramo local no puede quedar por debajo del estatal"}', 0, 1, NULL, 'GBIF: 38 ocurrencias dentro de los polígonos de hábitat del espacio (6 hábitats; barrido de 2026-08-16); EIDOS (IEPNB, MITECO) para la taxonomía; sin figura de protección en la vista de normas', 'Tracheophyta', 'Magnoliopsida', 'Fagales', 'Fagaceae', 'Quercus', 'LC (Preocupación menor)', 'No localizada en la Lista Roja de la Flora Vascular Española 2008 (pendiente de confirmar)', 'No incluida en el Catálogo Regional de especies protegidas (Región de Murcia)', NULL, 7478, 2879175, NULL
    UNION ALL
    SELECT 'Aladierno', 'Rhamnus alaternus', 'flora', 'Arbusto', 'Matorral alto, encinares y barrancos sobre suelos pedregosos', 'Interés especial', 'Arbusto perennifolio de hojas alternas, coriáceas y de borde finamente dentado, sin espinas. Sus frutos maduran de rojo a negro y son muy buscados por los pájaros. Se distingue del espino negro por carecer de espinas y tener hojas mayores.', NULL, 'Sin espinas, a diferencia de otros ramnos; Hojas alternas, coriáceas y algo dentadas; Frutos que pasan de rojo a negro al madurar', 'Todo el año', 'https://commons.wikimedia.org/wiki/Special:FilePath/Rhamnus_alaternus1627.JPG?width=1280', 'tato grasso (CC BY-SA 2.5) · Wikimedia Commons', NULL, NULL, 1, '{"categoria":"Sin figura de protección","ambito":"estatal","origen":"spainStatus del catálogo universal"}', 3, '{"categoria":"Especies de interés especial","norma":"Decreto n.º 50/2003, de 30 de mayo por el que se crea el Catálogo Regional de Flora Silvestre Protegida de la Región de Murcia y se dictan Normas para el aprovechamiento de diversas especies forestales.","ambito":"Región de Murcia"}', 0, 1, NULL, 'GBIF: 36 ocurrencias dentro de los polígonos de hábitat del espacio (6 hábitats; barrido de 2026-08-16); EIDOS (IEPNB, MITECO) para la taxonomía y el estado legal', 'Tracheophyta', 'Magnoliopsida', 'Rosales', 'Rhamnaceae', 'Rhamnus', 'LC (Preocupación menor) (evaluación UICN 2018)', 'Sin figura de protección nacional específica registrada en EIDOS', 'Especies de interés especial (Decreto n.º 50/2003, de 30 de mayo por el que se crea el Catálogo Regional de Flora Silvestre Protegida de la Región de Murcia y se dictan Normas para el aprovechamiento de diversas especies forestales.)', NULL, 7684, 6371424, NULL
    UNION ALL
    SELECT 'Enebro de la miera', 'Juniperus oxycedrus', 'flora', 'Conífera', 'Matorral, pinares aclarados y laderas pedregosas', 'En Peligro de Extinción', 'Enebro de hojas aciculares y punzantes dispuestas de tres en tres, con dos bandas blancas en la cara superior que lo separan a simple vista de la sabina. Sus gálbulos son rojizos al madurar. De su madera se destilaba el aceite de miera.', NULL, 'Hojas punzantes en grupos de tres, no en escama; Dos rayas blancas en la cara superior de cada hoja; Gálbulos rojizos y brillantes al madurar', 'Todo el año', 'https://commons.wikimedia.org/wiki/Special:FilePath/Juniperus_oxycedrus_g1.jpg?width=1280', 'autor no indicado (CC BY-SA 3.0) · Wikimedia Commons', NULL, NULL, 1, '{"categoria":"Sin figura de protección","ambito":"estatal","origen":"spainStatus del catálogo universal"}', 5, '{"categoria":"En Peligro de Extinción","norma":"Decreto n.º 50/2003, de 30 de mayo por el que se crea el Catálogo Regional de Flora Silvestre Protegida de la Región de Murcia y se dictan Normas para el aprovechamiento de diversas especies forestales.","ambito":"Región de Murcia"}', 0, 1, NULL, 'GBIF: 33 ocurrencias dentro de los polígonos de hábitat del espacio (5 hábitats; barrido de 2026-08-16); EIDOS (IEPNB, MITECO) para la taxonomía y el estado legal', 'Tracheophyta', 'Pinopsida', 'Pinales', 'Cupressaceae', 'Juniperus', 'LC (Preocupación menor) (evaluación UICN 2013)', 'ANEXO I. 1) Lista de especies forestales para la aprobación de unidades de conservación genética in situ (Real Decreto 159/2022, de 1 de marzo, sobre conservación de los recursos genéticos foresta…); ANEXO I. 2) Lista de taxones forestales para conservación ex situ (Real Decreto 159/2022, de 1 de marzo, sobre conservación de los recursos genéticos foresta…); ANEXO XII. Especies a las que se refiere la disposición adicional tercera (otras especies forestales importantes para la selvicultura en España) (Real Decreto 289/2003, de 7 de marzo, sobre la comercialización de los materiales forestal…)', 'En Peligro de Extinción (Decreto n.º 50/2003, de 30 de mayo por el que se crea el Catálogo Regional de Flora Silvestre Protegida de la Región de Murcia y se dictan Normas para el aprovechamiento de diversas especies forestales.)', NULL, 5505, 2684451, NULL
    UNION ALL
    SELECT 'Acebuche', 'Olea europaea subsp. europaea', 'flora', 'Árbol', 'Matorral alto, laderas secas y barrancos del piso más cálido', 'LC', 'El acebuche es el olivo silvestre: mismo árbol, sin siglos de selección. Tiene las hojas más pequeñas y duras, las ramas jóvenes a menudo espinosas y aceitunas diminutas. Forma matorrales altos y es el árbol característico de las laderas cálidas mediterráneas.', NULL, 'Hojas pequeñas, verdes arriba y plateadas por debajo; Ramillas jóvenes rígidas y a veces espinosas; Aceitunas muy pequeñas, de poco más de un centímetro', 'Todo el año', 'https://commons.wikimedia.org/wiki/Special:FilePath/Ullastre_vell.JPG?width=1280', 'Antoni Salvà (CC BY-SA 4.0) · Wikimedia Commons', NULL, NULL, 1, '{"categoria":"Sin figura de protección","ambito":"estatal","origen":"spainStatus del catálogo universal"}', 1, NULL, 0, 1, NULL, 'GBIF: 31 ocurrencias dentro de los polígonos de hábitat del espacio (4 hábitats; barrido de 2026-08-16); EIDOS (IEPNB, MITECO) para la taxonomía; sin figura de protección en la vista de normas', 'Tracheophyta', 'Magnoliopsida', 'Lamiales', 'Oleaceae', 'Olea', 'LC', 'No catalogada en la Lista Roja de la Flora Vascular Española 2008', 'No incluida en el Catálogo Regional de especies protegidas (Región de Murcia)', NULL, NULL, 5415040, NULL
    UNION ALL
    SELECT 'Malva subovata', 'Malva subovata', 'flora', NULL, NULL, 'No catalogada', NULL, NULL, NULL, 'Diciembre a junio', 'https://commons.wikimedia.org/wiki/Special:FilePath/Lavatera_maritima_bicolor_''Tree_mallow''_(Malvaceae)_flower.jpg?width=1280', 'Magnus Manske (CC BY-SA 3.0) · Wikimedia Commons', NULL, NULL, 3, NULL, 3, '{"origen":"rarityScore estatal del catálogo universal: EIDOS no devolvió ninguna norma para este taxón al hacer la selección, y el tramo local no puede quedar por debajo del estatal"}', 0, 0, 'Sin descripción: ninguna fuente publica texto para este taxón. Oculta hasta redactarla.', 'GBIF: 28 ocurrencias dentro de los polígonos de hábitat del espacio (10 hábitats; barrido de 2026-08-16); EIDOS (IEPNB, MITECO) para la taxonomía; sin figura de protección en la vista de normas', 'Tracheophyta', 'Magnoliopsida', 'Malvales', 'Malvaceae', 'Malva', 'No evaluada en la Lista Roja mundial de la UICN', 'Sin figura de protección de ámbito estatal (LESRPE/CEEA) en EIDOS (IEPNB)', 'No incluida en el Catálogo Regional de especies protegidas (Región de Murcia)', NULL, 94816, 7279633, NULL
    UNION ALL
    SELECT 'Ardilla roja', 'Sciurus vulgaris', 'fauna', 'Roedor', 'Pinares y bosques con arbolado maduro y producción de piñones o frutos', 'LC', 'Ardilla arborícola de cola larga y esponjosa y orejas con pinceles de pelo más marcados en invierno. En los pinares mediterráneos su rastro más evidente son las piñas roídas hasta dejar solo el eje, abandonadas en tocones y piedras.', NULL, 'Piñas roídas hasta el raspón, apiladas en un mismo posadero; Cola larga y esponjosa que mantiene erguida al saltar; Pinceles de pelo en las orejas, sobre todo en invierno', 'Todo el año', 'https://commons.wikimedia.org/wiki/Special:FilePath/Eichh%C3%B6rnchen_D%C3%BCsseldorf_Hofgarten_edit.jpg?width=1280', 'Ray eye (CC BY-SA 2.0 de) · Wikimedia Commons', NULL, NULL, 1, '{"categoria":"Sin figura de protección","ambito":"estatal","origen":"spainStatus del catálogo universal"}', 1, NULL, 0, 1, NULL, 'GBIF: 27 ocurrencias dentro de los polígonos de hábitat del espacio (5 hábitats; barrido de 2026-08-16); EIDOS (IEPNB, MITECO) para la taxonomía; sin figura de protección en la vista de normas', 'Chordata', 'Mammalia', 'Rodentia', 'Sciuridae', 'Sciurus', 'LC (Preocupación menor) (evaluación UICN 2023)', 'Sin figura de protección de ámbito estatal (LESRPE/CEEA) en EIDOS (IEPNB)', 'No incluida en el Catálogo Regional de especies protegidas (Región de Murcia)', NULL, 12414, 8211070, NULL
    UNION ALL
    SELECT 'Tomillo blanco', 'Thymus membranaceus', 'flora', 'Mata aromática', 'Tomillares y matorral raso sobre suelos calizos secos', 'No catalogada', 'Tomillo endémico del sureste ibérico, fácil de reconocer por unas brácteas grandes, blancas y membranosas que rodean la inflorescencia y parecen pétalos. Ese conjunto vistoso, más que las flores en sí, es lo que atrae a los insectos.', NULL, 'Brácteas blancas grandes y papiráceas rodeando la flor; Cabezuelas terminales muy vistosas y redondeadas; Aroma intenso a tomillo al frotar', 'Primavera', 'https://commons.wikimedia.org/wiki/Special:FilePath/Thymus_membranaceus_(3).jpg?width=1280', 'Nanosanchez (CC BY-SA 4.0) · Wikimedia Commons', NULL, NULL, 1, '{"categoria":"Sin figura de protección","ambito":"estatal","origen":"spainStatus del catálogo universal"}', 1, NULL, 0, 1, NULL, 'GBIF: 27 ocurrencias dentro de los polígonos de hábitat del espacio (6 hábitats; barrido de 2026-08-16); EIDOS (IEPNB, MITECO) para la taxonomía; sin figura de protección en la vista de normas', 'Tracheophyta', 'Magnoliopsida', 'Lamiales', 'Lamiaceae', 'Thymus', 'No evaluada específicamente en la Lista Roja mundial de la UICN', 'Sin figura de protección nacional específica registrada en EIDOS', 'No incluida en el Catálogo Regional de especies protegidas (Región de Murcia)', NULL, 8931, 7306992, NULL
    UNION ALL
    SELECT 'Palmito', 'Chamaerops humilis', 'flora', 'Palmera', 'Matorral cálido, laderas soleadas y acantilados del piso termomediterráneo', 'Interés especial', 'La única palmera silvestre de Europa continental. Suele crecer en mata, con varios troncos cortos, aunque con los años puede levantar un tronco único. Sus hojas son abanicos rígidos con pecíolos muy espinosos. Del cogollo se sacaba el «palmito», y de las hojas, cordelería y escobas.', NULL, 'Hojas en abanico, rígidas y divididas en segmentos; Pecíolos con espinas fuertes en los bordes; Porte en mata, con varios troncos desde la base', 'Todo el año', 'https://commons.wikimedia.org/wiki/Special:FilePath/Chamaerops_humilis_Torreblanca.jpg?width=1280', 'Canaan (CC BY-SA 4.0) · Wikimedia Commons', NULL, NULL, 3, NULL, 3, '{"categoria":"Especies de interés especial","norma":"Decreto n.º 50/2003, de 30 de mayo por el que se crea el Catálogo Regional de Flora Silvestre Protegida de la Región de Murcia y se dictan Normas para el aprovechamiento de diversas especies forestales.","ambito":"Región de Murcia"}', 0, 1, NULL, 'GBIF: 26 ocurrencias dentro de los polígonos de hábitat del espacio (6 hábitats; barrido de 2026-08-16); EIDOS (IEPNB, MITECO) para la taxonomía y el estado legal', 'Tracheophyta', 'Liliopsida', 'Arecales', 'Arecaceae', 'Chamaerops', 'LC (Preocupación menor)', 'No localizada en la Lista Roja de la Flora Vascular Española 2008 (pendiente de confirmar)', 'Especies de interés especial (Decreto n.º 50/2003, de 30 de mayo por el que se crea el Catálogo Regional de Flora Silvestre Protegida de la Región de Murcia y se dictan Normas para el aprovechamiento de diversas especies forestales.)', NULL, 3518, 2736625, NULL
    UNION ALL
    SELECT 'Esparraguera blanca', 'Asparagus albus', 'flora', 'Arbusto', 'Matorral seco, ribazos y bajo arbustos en clima cálido', 'LC', 'Esparraguera de tallos blanquecinos y muy espinosos que pierde el follaje en verano y florece en otoño, al revés que casi todo el matorral. Lo que parecen hojas son ramillas finas agrupadas en haces. Sus brotes tiernos son los espárragos silvestres de recolección tradicional.', NULL, 'Tallos claros, casi blancos, con espinas fuertes; Ramillas finas agrupadas en manojitos; Florece en otoño, con flores blancas y olorosas', 'Otoño (floración)', 'https://commons.wikimedia.org/wiki/Special:FilePath/Art%C3%A0_-_Ermita_de_Betlem_-_Asparagus_albus_03_ies.jpg?width=1280', 'Frank Vincentz (CC BY-SA 3.0) · Wikimedia Commons', NULL, NULL, 1, '{"categoria":"Sin figura de protección","ambito":"estatal","origen":"spainStatus del catálogo universal"}', 1, NULL, 0, 1, NULL, 'GBIF: 25 ocurrencias dentro de los polígonos de hábitat del espacio (3 hábitats; barrido de 2026-08-16); EIDOS (IEPNB, MITECO) para la taxonomía; sin figura de protección en la vista de normas', 'Tracheophyta', 'Liliopsida', 'Asparagales', 'Asparagaceae', 'Asparagus', 'LC (Preocupación menor)', 'No incluida en la Lista Roja de la Flora Vascular Española (2008) ni en el LESRPE', 'No incluida en el Catálogo Regional de especies protegidas (Región de Murcia)', NULL, 2378, 2769019, NULL
    UNION ALL
    SELECT 'Narciso', 'Lapiedra martinezii', 'flora', 'Planta bulbosa', NULL, 'LC', NULL, NULL, NULL, 'Todo el año', 'https://commons.wikimedia.org/wiki/Special:FilePath/Lapiedra_martinezii_-_Flor_de_la_estrella.jpg?width=1280', 'Formater (CC BY-SA 4.0) · Wikimedia Commons', NULL, NULL, 1, '{"categoria":"Sin figura de protección","ambito":"estatal","origen":"spainStatus del catálogo universal"}', 1, NULL, 0, 0, 'Sin descripción: ninguna fuente publica texto para este taxón. Oculta hasta redactarla.', 'GBIF: 25 ocurrencias dentro de los polígonos de hábitat del espacio (10 hábitats; barrido de 2026-08-16); Atlas y Manual de los Hábitats de España (MITECO, 2005): especie característica de alguno de los HIC cartografiados aquí; EIDOS (IEPNB, MITECO) para la taxonomía; sin figura de protección en la vista de normas', 'Tracheophyta', 'Liliopsida', 'Asparagales', 'Amaryllidaceae', 'Lapiedra', 'LC — Preocupación menor (Lista Roja mundial de la UICN, 2018)', 'Sin figura de protección de ámbito estatal (LESRPE/CEEA) en EIDOS (IEPNB)', 'No incluida en el Catálogo Regional de especies protegidas (Región de Murcia)', NULL, 5653, 2860661, NULL
    UNION ALL
    SELECT 'Baladre', 'Nerium oleander', 'flora', 'Arbusto', 'Cauces de rambla y ramblizos con humedad subterránea y crecidas', 'LC', 'Arbusto de hojas coriáceas, alargadas y opuestas, que forma masas densas en el lecho de las ramblas y aguanta las riadas gracias a su raigambre. Florece en rosa intenso durante buena parte del verano. Toda la planta es muy tóxica, savia incluida.', NULL, 'Hojas duras y lanceoladas con el nervio central marcado; Flores rosas grandes en el extremo de las ramas; Frutos en vaina larga que se abre soltando semillas con vilano', 'Primavera y verano', 'https://commons.wikimedia.org/wiki/Special:FilePath/Nerium_oleander_flowers_leaves.jpg?width=1280', 'Alvesgaspar (CC BY 2.5) · Wikimedia Commons', NULL, NULL, 1, '{"categoria":"Sin figura de protección","ambito":"estatal","origen":"spainStatus del catálogo universal"}', 1, NULL, 0, 1, NULL, 'GBIF: 25 ocurrencias dentro de los polígonos de hábitat del espacio (4 hábitats; barrido de 2026-08-16); EIDOS (IEPNB, MITECO) para la taxonomía; sin figura de protección en la vista de normas', 'Tracheophyta', 'Magnoliopsida', 'Gentianales', 'Apocynaceae', 'Nerium', 'LC (Preocupación menor)', 'No incluida en la Lista Roja de la Flora Vascular Española (2008) ni en el LESRPE', 'No incluida en el Catálogo Regional de especies protegidas (Región de Murcia)', NULL, 6561, 3169756, NULL
    UNION ALL
    SELECT 'Lastón', 'Brachypodium retusum', 'flora', 'Gramínea', 'Pastizales, claros de matorral y ribazos sobre suelos calizos', 'LC', 'Gramínea perenne y rizomatosa que forma céspedes extensos en los claros del matorral mediterráneo. Sus hojas son cortas, rígidas y de punta roma. Es de las plantas que más rápido rebrota tras un incendio, gracias a sus rizomas subterráneos.', NULL, 'Céspedes extensos y bajos, no matas aisladas; Hojas cortas y rígidas, de punta redondeada; Espiguillas alineadas a un lado de un eje rígido', 'Primavera', 'https://commons.wikimedia.org/wiki/Special:FilePath/Brachypodium_retusum_espiga_seca.jpg?width=1280', 'Pere prlpz (CC BY-SA 2.5) · Wikimedia Commons', NULL, NULL, 1, '{"categoria":"Sin figura de protección","ambito":"estatal","origen":"spainStatus del catálogo universal"}', 1, NULL, 0, 1, NULL, 'GBIF: 24 ocurrencias dentro de los polígonos de hábitat del espacio (5 hábitats; barrido de 2026-08-16); EIDOS (IEPNB, MITECO) para la taxonomía; sin figura de protección en la vista de normas', 'Tracheophyta', 'Liliopsida', 'Poales', 'Poaceae', 'Brachypodium', 'LC (Preocupación menor)', 'No incluida en la Lista Roja de la Flora Vascular Española (2008) ni en el LESRPE', 'No incluida en el Catálogo Regional de especies protegidas (Región de Murcia)', NULL, 9931, 5676053, NULL
    UNION ALL
    SELECT 'Camaleón común', 'Chamaeleo chamaeleon', 'fauna', 'Reptil', 'Presente en zonas de costa por lo general, a baja altitud y sobre suelos arenosos', 'Protegida (LESRPE)', 'Especie de aspecto inconfundible: cuerpo aplanado lateralmente, ojos prominentes, cabeza con casco llamativo, cola prensil, escamas granulares y dedos distribuidos en disposición 3+2. Se registra dicromatismo sexual con un patrón de coloración corporal (o librea) muy complejo y relacionado con el sexo, estado reproductor y las necesidades de termorregulación. Longitud total máxima de 282 mm en machos y 301 en hembras.', NULL, NULL, 'Febrero a noviembre', 'https://commons.wikimedia.org/wiki/Special:FilePath/BennyTrapp_Chamaeleo_chamaeleon_Samos_Griechenland.jpg?width=1280', 'Benny Trapp (CC BY 3.0) · Wikimedia Commons', NULL, NULL, 2, '{"categoria":"LESRPE: En régimen de protección especial (Real Decreto 139/2011, de 4 de febrero)","ambito":"estatal","origen":"spainStatus del catálogo universal"}', 2, '{"categoria":"En régimen de protección especial","norma":"Real Decreto 139/2011, de 4 de febrero, para el desarrollo del Listado de Especies Silvestres en Régimen de Protección Especial y del Catálogo Español de Especies Amenazadas. BOE 46, de 23 de febrero de 2011","ambito":"España"}', 0, 1, NULL, 'GBIF: 24 ocurrencias dentro de los polígonos de hábitat del espacio (6 hábitats; barrido de 2026-08-16); EIDOS (IEPNB, MITECO) para la taxonomía y el estado legal', 'Chordata', 'Reptilia', 'Squamata', 'Chamaeleonidae', 'Chamaeleo', 'LC — Preocupación menor (Lista Roja mundial de la UICN, 2012)', 'LESRPE: En régimen de protección especial (Real Decreto 139/2011, de 4 de febrero) · Anexo V (Ley 42/2007, de 13 de diciembre)', 'No incluida en el Catálogo Regional de especies protegidas (Región de Murcia)', NULL, 10883, 2449051, NULL
    UNION ALL
    SELECT 'Carrasca', 'Quercus rotundifolia', 'flora', 'Árbol', 'Bosques y matorrales mediterráneos continentales, sobre suelos secos y pobres', 'Interés especial', 'La encina de interior, más adaptada al frío y a la sequía continental, con hojas más redondeadas y bellotas dulces. A menudo crece en mata por el efecto del ramoneo y las cortas repetidas. Muchos autores la consideran una subespecie de la encina.', NULL, 'Hojas más redondeadas y pequeñas que las de la encina litoral; Bellotas de sabor dulce, no amargas; Frecuente en porte de mata, con varios pies', 'Todo el año', 'https://commons.wikimedia.org/wiki/Special:FilePath/Carrasca_de_la_Raboseras.JPG?width=1280', 'Picamaderos (CC BY-SA 3.0) · Wikimedia Commons', NULL, NULL, 1, '{"categoria":"Sin figura de protección","ambito":"estatal","origen":"spainStatus del catálogo universal"}', 3, '{"categoria":"Especies de interés especial","norma":"Decreto n.º 50/2003, de 30 de mayo por el que se crea el Catálogo Regional de Flora Silvestre Protegida de la Región de Murcia y se dictan Normas para el aprovechamiento de diversas especies forestales.","ambito":"Región de Murcia"}', 0, 1, NULL, 'GBIF: 24 ocurrencias dentro de los polígonos de hábitat del espacio (5 hábitats; barrido de 2026-08-16); EIDOS (IEPNB, MITECO) para la taxonomía y el estado legal', 'Tracheophyta', 'Magnoliopsida', 'Fagales', 'Fagaceae', 'Quercus', 'LC (Preocupación menor) (evaluación UICN 2018)', 'Sin figura de protección nacional específica registrada en EIDOS', 'Especies de interés especial (Decreto n.º 50/2003, de 30 de mayo por el que se crea el Catálogo Regional de Flora Silvestre Protegida de la Región de Murcia y se dictan Normas para el aprovechamiento de diversas especies forestales.)', NULL, 7379, 2881550, NULL
    UNION ALL
    SELECT 'Azufaifo', 'Ziziphus lotus', 'flora', 'Arbusto', 'Matorrales arborescentes de Ziziphus', 'Vulnerable', 'Arbusto espinoso que forma cúpulas densas de varios metros, un microhábitat en sí mismo: bajo su copa se refugian aves, reptiles y mamíferos, y la humedad y el suelo son distintos que fuera. Sus ramas zigzaguean con dos espinas en cada nudo, una recta y otra ganchuda.', NULL, 'Ramas en zigzag con dos espinas por nudo, una recta y otra curva; Porte en cúpula o almohadón, muy denso; Frutos redondos que pasan de verde a pardo amarillento', 'Primavera a otoño', 'https://commons.wikimedia.org/wiki/Special:FilePath/Ziziphus_lotus_20200928_191923.jpg?width=1280', 'Nanosanchez (CC BY-SA 4.0) · Wikimedia Commons', NULL, NULL, 4, NULL, 4, '{"categoria":"Vulnerable","norma":"Decreto n.º 50/2003, de 30 de mayo por el que se crea el Catálogo Regional de Flora Silvestre Protegida de la Región de Murcia y se dictan Normas para el aprovechamiento de diversas especies forestales.","ambito":"Región de Murcia"}', 1, 1, NULL, 'GBIF: 23 ocurrencias dentro de los polígonos de hábitat del espacio (7 hábitats; barrido de 2026-08-16); EIDOS (IEPNB, MITECO) para la taxonomía y el estado legal', 'Tracheophyta', 'Magnoliopsida', 'Rosales', 'Rhamnaceae', 'Ziziphus', 'NE (no evaluada a nivel global)', 'Incluida en la Lista Roja de la Flora Vascular Española 2008 (categoría exacta pendiente de confirmar en listaroja.conservacionvegetal.org)', 'Vulnerable (Decreto n.º 50/2003, de 30 de mayo por el que se crea el Catálogo Regional de Flora Silvestre Protegida de la Región de Murcia y se dictan Normas para el aprovechamiento de diversas especies forestales.)', NULL, 9441, 3039418, NULL
    UNION ALL
    SELECT 'Esparraguera de gato', 'Asparagus horridus', 'flora', 'Arbusto', 'Matorrales arborescentes de Juniperus spp.', 'LC', 'Esparraguera muy espinosa y densa que se enreda entre el matorral y el sabinar litoral, con cladodios rígidos y punzantes.', NULL, 'Cladodios rígidos y punzantes; Se enreda en el matorral; Frutos negros en otoño', 'Otoño', 'https://commons.wikimedia.org/wiki/Special:FilePath/Asparagus_stipularis_(detail).jpg?width=1280', 'Hans Hillewaert (CC BY-SA 3.0) · Wikimedia Commons', NULL, NULL, 1, '{"categoria":"Sin figura de protección","ambito":"estatal","origen":"spainStatus del catálogo universal"}', 1, NULL, 0, 1, NULL, 'GBIF: 22 ocurrencias dentro de los polígonos de hábitat del espacio (4 hábitats; barrido de 2026-08-16); EIDOS (IEPNB, MITECO) para la taxonomía; sin figura de protección en la vista de normas', 'Tracheophyta', 'Liliopsida', 'Asparagales', 'Asparagaceae', 'Asparagus', 'LC', 'No incluida en el LESRPE; acompañante de sabinares y matorrales termófilos (HIC 5210)', 'No incluida en el Catálogo Regional de especies protegidas (Región de Murcia)', NULL, 33035, 2768695, NULL
    UNION ALL
