    SELECT 'Rascavieja', 'Ononis speciosa', 'flora', 'Arbusto', 'Matorral seco y laderas soleadas sobre suelos pedregosos', 'Interés especial', 'Leguminosa arbustiva y pegajosa, con hojas de tres foliolos y racimos densos y erguidos de flores de un amarillo intenso. Es un endemismo del sur peninsular y del norte de África, y una de las plantas más vistosas del matorral en plena floración.', NULL, 'Racimos densos y erguidos de flores amarillo vivo; Toda la planta pegajosa por los pelos glandulosos; Hojas de tres foliolos dentados', 'Primavera', 'https://inaturalist-open-data.s3.amazonaws.com/photos/184117054/original.jpeg', 'Santiago Martín-Bravo (CC BY 4.0) · iNaturalist/GBIF', NULL, NULL, 1, '{"categoria":"Sin figura de protección","ambito":"estatal","origen":"spainStatus del catálogo universal"}', 3, '{"categoria":"Especies de interés especial","norma":"Decreto n.º 50/2003, de 30 de mayo por el que se crea el Catálogo Regional de Flora Silvestre Protegida de la Región de Murcia y se dictan Normas para el aprovechamiento de diversas especies forestales.","ambito":"Región de Murcia"}', 0, 1, NULL, 'GBIF: 4 ocurrencias dentro de los polígonos de hábitat del espacio (3 hábitats; barrido de 2026-08-16); EIDOS (IEPNB, MITECO) para la taxonomía y el estado legal', 'Tracheophyta', 'Magnoliopsida', 'Fabales', 'Fabaceae', 'Ononis', 'No evaluada específicamente en la Lista Roja mundial de la UICN', 'Sin figura de protección nacional específica registrada en EIDOS', 'Especies de interés especial (Decreto n.º 50/2003, de 30 de mayo por el que se crea el Catálogo Regional de Flora Silvestre Protegida de la Región de Murcia y se dictan Normas para el aprovechamiento de diversas especies forestales.)', NULL, 6712, 2977276, NULL
    UNION ALL
    SELECT 'Bayón', 'Osyris lanceolata', 'flora', 'Arbusto', 'Matorral alto, sabinares y laderas secas sobre suelo pedregoso', 'Interés especial', 'Arbusto de ramas verdes y erguidas con hojas estrechas y coriáceas. Es hemiparásito: fabrica su propio alimento pero además conecta sus raíces a las de otras plantas para robarles agua y sales. Sus frutos son bayas rojas o anaranjadas muy vistosas.', NULL, 'Ramas verdes y erectas, de aspecto escobiforme; Bayas rojo anaranjado brillantes al madurar; Hojas estrechas, duras y de punta aguda', 'Todo el año', 'https://commons.wikimedia.org/wiki/Special:FilePath/Osyris_lanceolata.JPG?width=1280', 'Xemenendura (CC BY-SA 4.0) · Wikimedia Commons', NULL, NULL, 3, NULL, 3, '{"categoria":"Especies de interés especial","norma":"Decreto n.º 50/2003, de 30 de mayo por el que se crea el Catálogo Regional de Flora Silvestre Protegida de la Región de Murcia y se dictan Normas para el aprovechamiento de diversas especies forestales.","ambito":"Región de Murcia"}', 0, 1, NULL, 'GBIF: 4 ocurrencias dentro de los polígonos de hábitat del espacio (6 hábitats; barrido de 2026-08-16); EIDOS (IEPNB, MITECO) para la taxonomía y el estado legal', 'Tracheophyta', 'Magnoliopsida', 'Santalales', 'Santalaceae', 'Osyris', 'LC (Preocupación menor)', 'No localizada en la Lista Roja de la Flora Vascular Española 2008 (pendiente de confirmar)', 'Especies de interés especial (Decreto n.º 50/2003, de 30 de mayo por el que se crea el Catálogo Regional de Flora Silvestre Protegida de la Región de Murcia y se dictan Normas para el aprovechamiento de diversas especies forestales.)', NULL, 6882, 7473922, NULL
    UNION ALL
